# Generated by batocera/tools/gen_identifier.py: edit that file, not this one.
#
# As a Port: copy it to /userdata/roms/ports/ and launch it, or over SSH:  bash "Identifier NFSMW.sh" [folder]
# It finds every default.xex under /userdata and /media (or takes the folder given), hashes the files and writes
# /userdata/roms/ports/nfsmw-identification.txt. About a minute or two per copy (~7 GB). Nothing is changed.
HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="$HERE/nfsmw-identification.txt"
