report() {
  local DIR="$1" xex ed list data ok bad missing hash size path
  echo
  echo "################ $DIR"
  xex=$(sha256sum "$DIR/default.xex" | cut -d' ' -f1)
  echo "default.xex sha256: $xex  size: $(stat -c %s "$DIR/default.xex")"
  ed=$(echo "$EDITIONS" | grep "^$xex " | cut -d' ' -f2-)
  echo "edition: ${ed:-UNKNOWN (modified or unlisted executable)}"
  # nfsmw-nx tools/french-dub (PAL English -> French): ZDIR.BIN points ENGLISH.BIN at FRENCH.BIN, new ZZDATA9.
  if [ -f "$DIR/NFS/ZDIR.BIN" ]; then
    echo "NFS/ZDIR.BIN sha256: $(sha256sum "$DIR/NFS/ZDIR.BIN" | cut -d' ' -f1)"
  fi
  if ls "$DIR"/Movies/*french* >/dev/null 2>&1; then echo "Movies: French-named files present"; fi
  echo "-- files"
  (cd "$DIR" && find . -type f | sed 's|^\./||' | sort | while read -r f; do echo "$(stat -c %s "$f") $f"; done)
  for list in USA PAL_ES; do
    if [ $list = USA ]; then data="$SB_USA"; else data="$SB_PAL_ES"; fi
    ok=0; bad=0; missing=0
    echo "-- SpeedBreaker $list check"
    while read -r hash size path; do
      [ -n "$path" ] || continue
      if [ ! -f "$DIR/$path" ]; then missing=$((missing+1)); continue; fi
      if [ "$(stat -c %s "$DIR/$path")" != "$size" ]; then echo "  SIZE     $path"; bad=$((bad+1)); continue; fi
      if [ "$(sha256sum "$DIR/$path" | cut -d' ' -f1)" != "$hash" ]; then echo "  CHANGED  $path"; bad=$((bad+1)); continue; fi
      ok=$((ok+1))
    done <<< "$data"
    echo "  $ok identical, $bad different, $missing missing (of 49)"
  done
}

# The folder given, else every default.xex under /userdata (roms, ports, USB/SD mounts under /media too).
if [ -n "${1:-}" ]; then
  DIRS="$1"
else
  DIRS=$(find /userdata /media "$HERE" -maxdepth 7 -type f -iname default.xex 2>/dev/null | while read -r f; do dirname "$f"; done | sort -u)
fi
if [ -z "$DIRS" ]; then
  echo "no default.xex found under /userdata or /media."
  echo "Copy the extracted game (default.xex, NFS/, Movies/) to /userdata/roms/ports/speedbreaker/disc/ and run again."
  echo "ISO images found (not opened):"
  find /userdata /media -maxdepth 7 -type f -iname '*.iso' -size +1G 2>/dev/null | while read -r f; do echo "  $(stat -c %s "$f") $f"; done
  exit 1
fi
while read -r d; do [ -n "$d" ] && report "$d"; done <<< "$DIRS"
echo
echo "== done"
